DECLARE @student_no varchar(15)=?,@student_name nvarchar(16)=?,@student_name_kana nvarchar(36)=?,@birth_date date=?,@gender_code varchar(1)=?,@postal_code varchar(7)=?,@prefecture_code varchar(2)=?,@address_line1 nvarchar(90)=?,@address_line2 nvarchar(90)=?,@phone_number varchar(16)=?,@email_address varchar(60)=?,@admission_date date=?,@enrollment_status_code varchar(2)=?,@enrollment_end_date date=?,@class_id bigint=?,@emergency_contact_name nvarchar(16)=?,@relationship_code varchar(2)=?,@emergency_phone_number varchar(16)=?,@remarks nvarchar(240)=?,@name_key nvarchar(320)=?,@kana_key nvarchar(36)=?,@relationship_category varchar(24)=?,@actor nvarchar(128)=?,@now datetimeoffset(7)=?; DECLARE @changed TABLE(id bigint); INSERT INTO dbo.m_student (student_no,student_name,student_name_kana,birth_date,gender_code,postal_code,prefecture_code,address_line1,address_line2,phone_number,email_address,admission_date,enrollment_status_code,enrollment_end_date,class_id,emergency_contact_name,relationship_code,emergency_phone_number,remarks,name_key,kana_key,relationship_category,gender_category,prefecture_category,enrollment_category,is_deleted,created_at,created_by,updated_at,updated_by,row_version) OUTPUT INSERTED.student_id INTO @changed VALUES (@student_no,@student_name,@student_name_kana,@birth_date,@gender_code,@postal_code,@prefecture_code,@address_line1,@address_line2,@phone_number,@email_address,@admission_date,@enrollment_status_code,@enrollment_end_date,@class_id,@emergency_contact_name,@relationship_code,@emergency_phone_number,@remarks,@name_key,@kana_key,@relationship_category,'GENDER','PREFECTURE','ENROLLMENT_STATUS',0,@now,@actor,@now,@actor,1); SELECT id FROM @changed;
